          {/* 右侧：走势图 */}
          <div>
            <div className="bg-white rounded-md p-2 shadow-sm h-full">
              <h4 className="text-xs font-medium text-gray-700 mb-1">近一个月走势</h4>
              <div className="text-xs text-gray-500 mb-1">{assetName}</div>
