          <rect width="100%" height="100%" fill="url(#grid-bond)" />

          {/* 价格线 */}
          <polyline
            fill="none"
            stroke="#10B981"
            strokeWidth="2"
            points={points}
          />

          {/* 填充区域 */}
          <polygon
            fill="rgba(16, 185, 129, 0.1)"
            points={`${padding},${height - padding} ${points} ${width - padding},${height - padding}`}
          />

          {/* 数据点 */}
          {priceData.map((item, index) => {
            const x = padding + (index / (priceData.length - 1)) * (width - 2 * padding);
            const y = height - padding - ((item.price - minPrice) / priceRange) * (height - 2 * padding);
            return (
              <circle
